public void recomputeNormalizedWeights(double[] weights) {
    cumulativeProb = new double[weights.length];
    cumulativeProb[0] = weights[0];
    for (int i = 1; i  weights.length; i++) {
        cumulativeProb[i] = weights[i] + cumulativeProb[i - 1];
    }
}

