    if (commaSeparList == null) return null;
    String[] items = commaSeparList.split(",");
    File[] files = new File[items.length];
    for (int i = 0; i  items.length; i++) {
        files[i] = new File(items[i]);
        if (files[i].canRead() == false) return null;
    }
    Arrays.sort(files);
    return files;
}

