private static double npv(double rate, double[] values) {
    double[] npv = new double[values.length];
    for (int i = 0; i  values.length; i++) {
        npv[i] = values[i] / Math.pow((1 + rate), i + 1);
    }
    return UtilFns.getStats(npv).getSum();
}

