public static Pattern[] push(Pattern newTail, Pattern[] pataIn) {
    Pattern[] pataOut = new Pattern[pataIn.length + 1];
    for (int i = 0; i  pataIn.length; i++) {
        pataOut[i] = pataIn[i];
    }
    pataOut[pataOut.length - 1] = newTail;
    return pataOut;
}

