private void addNode(NeuralConnection n) {
    NeuralConnection[] temp1 = new NeuralConnection[m_neuralNodes.length + 1];
    for (int noa = 0; noa  m_neuralNodes.length; noa++) {
        temp1[noa] = m_neuralNodes[noa];
    }
    temp1[temp1.length - 1] = n;
    m_neuralNodes = temp1;
}

