public static String getMD5Str(String password) {
    char[] pw = new char[password.length()];
    for (int i = 0; i  pw.length; i++) {
        pw[i] = password.charAt(i);
    }
    try {
        return new String(Md5Util.cryptPassword(pw));
    } catch (Exception e) {
        e.printStackTrace();
    }
    return null;
}

