public byte[][] executeBatch(byte[][] commands, MessageContext[] msgCtxs) {
    stateLock.lock();
    byte[][] replies = new byte[commands.length][];
    for (int i = 0; i  commands.length; i++) {
        replies[i] = execute(commands[i], msgCtxs[i]);
    }
    stateLock.unlock();
    return replies;
}

